CREATE TABLE "VideoAsset" ("id" TEXT NOT NULL PRIMARY KEY,"organisationId" TEXT NOT NULL,"gymnastId" TEXT,"createdByMembershipId" TEXT NOT NULL,"title" TEXT NOT NULL,"apparatus" TEXT,"skillLabel" TEXT,"routineId" TEXT,"routineItemId" TEXT,"cameraAngle" TEXT,"sourceType" TEXT NOT NULL DEFAULT 'LOCAL',"fileName" TEXT,"mimeType" TEXT,"durationSeconds" REAL,"storageRef" TEXT,"status" TEXT NOT NULL DEFAULT 'ACTIVE',"notes" TEXT,"createdAt" DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" DATETIME NOT NULL);
CREATE INDEX "VideoAsset_organisationId_status_createdAt_idx" ON "VideoAsset"("organisationId","status","createdAt");
CREATE INDEX "VideoAsset_gymnastId_createdAt_idx" ON "VideoAsset"("gymnastId","createdAt");
CREATE INDEX "VideoAsset_routineId_createdAt_idx" ON "VideoAsset"("routineId","createdAt");
CREATE TABLE "VideoAnalysis" ("id" TEXT NOT NULL PRIMARY KEY,"organisationId" TEXT NOT NULL,"videoAssetId" TEXT NOT NULL,"authorMembershipId" TEXT NOT NULL,"title" TEXT NOT NULL,"timestampSeconds" REAL,"rangeStartSeconds" REAL,"rangeEndSeconds" REAL,"playbackRate" REAL,"zoom" REAL,"panX" REAL,"panY" REAL,"comparisonMode" TEXT,"comparisonAssetId" TEXT,"comparisonOffset" REAL,"overlayOpacity" REAL,"annotationJson" TEXT NOT NULL DEFAULT '[]',"technicalTags" TEXT NOT NULL DEFAULT '[]',"observation" TEXT,"createdAt" DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" DATETIME NOT NULL);
CREATE INDEX "VideoAnalysis_organisationId_videoAssetId_createdAt_idx" ON "VideoAnalysis"("organisationId","videoAssetId","createdAt");
CREATE INDEX "VideoAnalysis_videoAssetId_timestampSeconds_idx" ON "VideoAnalysis"("videoAssetId","timestampSeconds");